mapper.update:
update play_team_member
set status = #{toStatus}, update_time = now()
where team_id = #{teamId} and member_id = #{memberId} and status = #{fromStatus}

update play_team_member
set role = #{toRole}, update_time = now()
where team_id = #{teamId} and member_id = #{memberId} and status = 1 and role = #{fromRole}

update play_team t
left join cms_activity activity on t.owner_type = 2 and activity.id = t.owner_id
left join cms_topic topic on topic.id = activity.topic_id
left join game_session game on t.owner_type = 2 and game.activity_id = t.owner_id
set t.status = 3, t.update_time = now()
where t.id = #{teamId}
  and t.status in (0, 1)
  and t.expire_time <= #{now}
  and (
    (game.id is null and topic.game_module_config_json is null)
    or activity.end_date <= #{now}
  )
